import {cleanPublicDesign} from './public-design.js';
import {compressGiftPhotos} from './media-compression.js';
import {ornamentArtwork} from './gift-identity.js';
import {giftContentPages} from './experience.js';
import {bookTexturePaths,resolveBookFinish} from './book-finish.js';
import {giftArtworkSource,giftOpeningSource} from './appearance.js';
const fileText=async path=>{const response=await fetch(path);if(!response.ok)throw Error('Não foi possível carregar '+path);return response.text();};
const dataURL=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});
const strip=source=>source.replace(/^import .*?;\s*/gm,'').replace(/\bexport (?=(?:async )?function|const )/g,'');
const safeJSON=value=>JSON.stringify(value).replaceAll('<','\\u003c').replaceAll('\u2028','\\u2028').replaceAll('\u2029','\\u2029');
export async function makePortableObject(data,audio){
 data=await compressGiftPhotos(data);
 const [three,book,layout,appearance,motion,identity,finish,stationery,reader,experience,sound,baseCSS,portableCSS,fonts]=await Promise.all(['assets/vendor/three.module.js','book.js','text-layout.js','appearance.js','motion-3d.js','gift-identity.js','book-finish.js','stationery.js','portable-reader.js','experience.js','audio-studio.js','digital.css','portable.css','fonts.css'].map(fileText));
 let fontCSS=fonts;for(const match of fonts.matchAll(/url\(([^)]+)\)/g)){const response=await fetch(match[1]);if(!response.ok)throw Error('Fonte indisponível');fontCSS=fontCSS.replace(match[0],'url('+await dataURL(await response.blob())+')');}
 const portableAssets={};for(const path of [...Object.values(ornamentArtwork),'assets/'+(data.theme?.sheet||'classic')+'.webp','assets/material-'+(data.texture||'algodao')+'.webp',giftArtworkSource(data),giftOpeningSource(data),'assets/hero-motion-envelope.webp',...(data.format==='livro'?bookTexturePaths(resolveBookFinish(data)):[])]){const response=await fetch(path);if(response.ok)portableAssets[path]=await dataURL(await response.blob());}
 const image=async src=>{if(!src)return null;if(src.startsWith('data:'))return src;const response=await fetch(src);if(!response.ok)throw Error('Foto indisponível');return dataURL(await response.blob());};
 const photos=await Promise.all((data.photos||[]).map(async photo=>({...photo,src:await image(photo.src)}))),pages=await Promise.all(giftContentPages(data).map(async page=>({...page,photo:await image(page.photo)})));
 const payload={...cleanPublicDesign(data,photos),occasion:data.occasion,openingAssetUrl:portableAssets[giftOpeningSource(data)],coverPhoto:await image(data.coverPhoto??(data.format==='livro'?data.pages?.[0]?.photo:data.photo)??data.photo),draftId:data.draftId,format:data.format,recipient:data.recipient,message:data.format==='livro'&&data.pages?.length?data.pages[0].message:data.message,color:data.color,character:data.character,person:data.person,texture:data.texture,pattern:data.pattern,coverArt:data.coverArt,openingStyle:data.openingStyle,theme:data.theme,photo:await image(data.format==='livro'&&data.pages?.length?data.pages[0].photo:data.photo),photos,pages,experience:data.experience,storyDesign:data.storyDesign,bookFinish:resolveBookFinish(data),stationeryDesign:data.stationeryDesign,appearance:data.appearance,eventDate:data.eventDate,eventPlace:data.eventPlace,guestPreview:data.guestPreview?{id:data.guestPreview.id,name:data.guestPreview.name,allowedCount:data.guestPreview.allowedCount}:undefined,portableAssets,audioUrl:audio?.blob?await dataURL(audio.blob):''};
 const threeURL=await dataURL(new Blob([three],{type:'text/javascript'})),bookRuntime=strip(book).replace('function image(src){','function image(src){src=window.__capimimoAssets?.[src]||src;');
 const drawCover='function drawCover(ctx,img,x,y,w,h){const scale=Math.max(w/img.width,h/img.height),dw=img.width*scale,dh=img.height*scale;ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.drawImage(img,x+(w-dw)/2,y+(h-dh)/2,dw,dh);ctx.restore();}';
 const engine=`async function openObject(){const THREE=await import(${safeJSON(threeURL)});${strip(layout)}\n${strip(appearance)}\n${strip(motion)}\n${strip(identity)}\n${strip(finish)}\n${strip(stationery)}\n${drawCover}\n${bookRuntime}\nawait document.fonts.ready;await mountPortableGift(gift,createBook);}`;
 const runtime=[strip(experience),strip(sound.split('export function initAudioStudio')[0]),strip(reader),'const gift=JSON.parse(document.getElementById("capimimo-payload").textContent);window.__capimimoAssets=gift.portableAssets;',engine,"openObject().catch(()=>{if(window.parent!==window)window.parent.postMessage({type:'capimimo:error'},'*');(document.getElementById('portable-loading')||document.body).textContent='Não foi possível iniciar a visualização neste navegador. Abra o arquivo em um navegador atualizado.';});"].join('\n').replace(/<\/script/gi,'<\\/script');
 return new Blob([`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Um mimo para você</title><style>${fontCSS}\n${baseCSS}\n${portableCSS}</style><body class="portable-body"><p id="portable-loading" style="padding:32px;text-align:center">Preparando seu presente…</p><script type="application/json" id="capimimo-payload">${safeJSON(payload)}<\/script><script>${runtime}<\/script></body></html>`],{type:'text/html;charset=utf-8'});
}
